#!/usr/bin/env bash
source "$(dirname "$0")/common.sh"
heading 'Paso 57 — curar Silver y materializar salidas Gold'
[[ -s "$ROOT/state/$DEMO_RUN_ID/batch_productivo_bronze_ok.txt" ]] || { echo 'SCRIPT 57: 0 — dependencia: SCRIPT 56'; exit 1; }
BATCH_RUN_ID="$(cat "$ROOT/state/$DEMO_RUN_ID/batch_productivo_id.txt")"
LOCATION="$(sed -n 's/^dataset_location=//p' "$ROOT/state/$DEMO_RUN_ID/batch_productivo_preflight.txt")"
Q() { bq --project_id="$PROJECT_ID" --location="$LOCATION" query --use_legacy_sql=false --maximum_bytes_billed=104857600 "$1" >/dev/null; }
Q "MERGE \`$PROJECT_ID.$SILVER_DATASET.pedidos\` T USING (SELECT JSON_VALUE(payload_json,'$.order_id') order_id,JSON_VALUE(payload_json,'$.order_line_id') order_line_id,JSON_VALUE(payload_json,'$.customer_id') customer_id,JSON_VALUE(payload_json,'$.store_id') store_id,JSON_VALUE(payload_json,'$.warehouse_id') warehouse_id,JSON_VALUE(payload_json,'$.sku_id') sku_id,SAFE_CAST(JSON_VALUE(payload_json,'$.quantity') AS INT64) quantity,effective_at occurred_at,IF(is_valid AND SAFE_CAST(JSON_VALUE(payload_json,'$.quantity') AS INT64)>0,'VALID','INVALID') quality_status FROM \`$PROJECT_ID.$BRONZE_DATASET.pedidos_raw\` WHERE batch_id='$BATCH_RUN_ID') S ON T.order_id=S.order_id AND COALESCE(T.order_line_id,'')=COALESCE(S.order_line_id,'') WHEN NOT MATCHED THEN INSERT ROW"
Q "MERGE \`$PROJECT_ID.$SILVER_DATASET.inventario\` T USING (SELECT CONCAT(batch_id,':',file_id,':',CAST(source_row_number AS STRING)) snapshot_id,JSON_VALUE(payload_json,'$.warehouse_id') warehouse_id,JSON_VALUE(payload_json,'$.store_id') store_id,JSON_VALUE(payload_json,'$.sku_id') sku_id,SAFE_CAST(JSON_VALUE(payload_json,'$.on_hand_qty') AS INT64) on_hand_qty,SAFE_CAST(JSON_VALUE(payload_json,'$.reserved_qty') AS INT64) reserved_qty,effective_at,IF(is_valid AND SAFE_CAST(JSON_VALUE(payload_json,'$.on_hand_qty') AS INT64)>=SAFE_CAST(JSON_VALUE(payload_json,'$.reserved_qty') AS INT64),'VALID','INVALID') quality_status FROM \`$PROJECT_ID.$BRONZE_DATASET.inventario_raw\` WHERE batch_id='$BATCH_RUN_ID') S ON T.snapshot_id=S.snapshot_id WHEN NOT MATCHED THEN INSERT ROW"
Q "MERGE \`$PROJECT_ID.$SILVER_DATASET.entregas\` T USING (SELECT JSON_VALUE(payload_json,'$.delivery_id') delivery_id,JSON_VALUE(payload_json,'$.order_id') order_id,JSON_VALUE(payload_json,'$.store_id') store_id,JSON_VALUE(payload_json,'$.region_id') region_id,SAFE_CAST(JSON_VALUE(payload_json,'$.promised_at') AS TIMESTAMP) promised_at,SAFE_CAST(JSON_VALUE(payload_json,'$.delivered_at') AS TIMESTAMP) delivered_at,SAFE_CAST(JSON_VALUE(payload_json,'$.delivery_cost') AS NUMERIC) delivery_cost,IF(is_valid AND SAFE_CAST(JSON_VALUE(payload_json,'$.delivery_cost') AS NUMERIC)>=0,'VALID','INVALID') quality_status FROM \`$PROJECT_ID.$BRONZE_DATASET.entregas_raw\` WHERE batch_id='$BATCH_RUN_ID') S ON T.delivery_id=S.delivery_id WHEN NOT MATCHED THEN INSERT ROW"
Q "MERGE \`$PROJECT_ID.$SILVER_DATASET.benchmark_competidores\` T USING (SELECT JSON_VALUE(payload_json,'$.benchmark_id') benchmark_id,JSON_VALUE(payload_json,'$.competitor_id') competitor_id,JSON_VALUE(payload_json,'$.sku_id') sku_id,JSON_VALUE(payload_json,'$.store_id') store_id,SAFE_CAST(JSON_VALUE(payload_json,'$.observed_at') AS TIMESTAMP) observed_at,SAFE_CAST(JSON_VALUE(payload_json,'$.competitor_price') AS NUMERIC) competitor_price,JSON_VALUE(payload_json,'$.availability') availability,IF(is_valid AND SAFE_CAST(JSON_VALUE(payload_json,'$.competitor_price') AS NUMERIC)>0,'VALID','INVALID') quality_status FROM \`$PROJECT_ID.$BRONZE_DATASET.benchmark_competidores_raw\` WHERE batch_id='$BATCH_RUN_ID') S ON T.benchmark_id=S.benchmark_id WHEN NOT MATCHED THEN INSERT ROW"
Q "MERGE \`$PROJECT_ID.$SILVER_DATASET.eventos_locales\` T USING (SELECT JSON_VALUE(payload_json,'$.local_event_id') local_event_id,JSON_VALUE(payload_json,'$.store_id') store_id,JSON_VALUE(payload_json,'$.event_type') event_type,SAFE_CAST(JSON_VALUE(payload_json,'$.start_at') AS TIMESTAMP) start_at,SAFE_CAST(JSON_VALUE(payload_json,'$.end_at') AS TIMESTAMP) end_at,SAFE_CAST(JSON_VALUE(payload_json,'$.impact_score') AS FLOAT64) impact_score,IF(is_valid AND SAFE_CAST(JSON_VALUE(payload_json,'$.impact_score') AS FLOAT64) BETWEEN 0 AND 1,'VALID','INVALID') quality_status FROM \`$PROJECT_ID.$BRONZE_DATASET.eventos_locales_raw\` WHERE batch_id='$BATCH_RUN_ID') S ON T.local_event_id=S.local_event_id WHEN NOT MATCHED THEN INSERT ROW"
Q "MERGE \`$PROJECT_ID.$SILVER_DATASET.redes_sociales\` T USING (SELECT JSON_VALUE(payload_json,'$.post_id') post_id,JSON_VALUE(payload_json,'$.platform') platform,SAFE_CAST(JSON_VALUE(payload_json,'$.published_at') AS TIMESTAMP) published_at,JSON_VALUE(payload_json,'$.sku_id') sku_id,SAFE_CAST(JSON_VALUE(payload_json,'$.sentiment_score') AS FLOAT64) sentiment_score,SAFE_CAST(JSON_VALUE(payload_json,'$.engagement_count') AS INT64) engagement_count,JSON_VALUE(payload_json,'$.text_hash') text_hash,IF(is_valid AND SAFE_CAST(JSON_VALUE(payload_json,'$.sentiment_score') AS FLOAT64) BETWEEN -1 AND 1 AND SAFE_CAST(JSON_VALUE(payload_json,'$.engagement_count') AS INT64)>=0,'VALID','INVALID') quality_status FROM \`$PROJECT_ID.$BRONZE_DATASET.redes_sociales_raw\` WHERE batch_id='$BATCH_RUN_ID') S ON T.post_id=S.post_id WHEN NOT MATCHED THEN INSERT ROW"
Q "DELETE FROM \`$PROJECT_ID.$GOLD_DATASET.cu01_riesgo_quiebre_despacho\` WHERE scenario_id='$BATCH_RUN_ID'; INSERT INTO \`$PROJECT_ID.$GOLD_DATASET.cu01_riesgo_quiebre_despacho\` SELECT '$BATCH_RUN_ID',i.sku_id,i.store_id,CAST(GREATEST(0,1-SAFE_DIVIDE(i.on_hand_qty-i.reserved_qty,NULLIF(i.on_hand_qty,0))) AS FLOAT64),i.on_hand_qty-i.reserved_qty,IF(i.on_hand_qty-i.reserved_qty<12,'REPOSICIONAR/DESPACHAR','MONITOREAR'),i.effective_at FROM \`$PROJECT_ID.$SILVER_DATASET.inventario\` i JOIN \`$PROJECT_ID.$SILVER_DATASET.pedidos\` p USING(sku_id) WHERE i.snapshot_id LIKE CONCAT('$BATCH_RUN_ID',':%') AND p.order_id='ORD-$BATCH_RUN_ID' AND i.quality_status='VALID' AND p.quality_status='VALID'"
Q "DELETE FROM \`$PROJECT_ID.$GOLD_DATASET.cu02_plan_reposicion\` WHERE scenario_id='$BATCH_RUN_ID'; INSERT INTO \`$PROJECT_ID.$GOLD_DATASET.cu02_plan_reposicion\` SELECT '$BATCH_RUN_ID',p.sku_id,i.warehouse_id,DATE(p.occurred_at),SUM(p.quantity),GREATEST(0,SUM(p.quantity)-(i.on_hand_qty-i.reserved_qty)),IF(i.on_hand_qty-i.reserved_qty<SUM(p.quantity),'HIGH','NORMAL') FROM \`$PROJECT_ID.$SILVER_DATASET.pedidos\` p JOIN \`$PROJECT_ID.$SILVER_DATASET.inventario\` i USING(sku_id) WHERE p.order_id='ORD-$BATCH_RUN_ID' AND i.snapshot_id LIKE CONCAT('$BATCH_RUN_ID',':%') AND p.quality_status='VALID' AND i.quality_status='VALID' GROUP BY p.sku_id,i.warehouse_id,DATE(p.occurred_at),i.on_hand_qty,i.reserved_qty"
Q "DELETE FROM \`$PROJECT_ID.$GOLD_DATASET.cu03_kpis_operativos\` WHERE scenario_id='$BATCH_RUN_ID'; INSERT INTO \`$PROJECT_ID.$GOLD_DATASET.cu03_kpis_operativos\` SELECT '$BATCH_RUN_ID',CURRENT_DATE(),'batch',COUNT(DISTINCT p.order_id),SUM(p.quantity),CAST(NULL AS FLOAT64),COALESCE(SUM(e.delivery_cost),0),SAFE_DIVIDE(COUNTIF(e.delivered_at IS NOT NULL),COUNT(e.delivery_id)) FROM \`$PROJECT_ID.$SILVER_DATASET.pedidos\` p LEFT JOIN \`$PROJECT_ID.$SILVER_DATASET.entregas\` e USING(order_id) WHERE p.order_id='ORD-$BATCH_RUN_ID' AND p.quality_status='VALID'"
Q "CREATE TABLE IF NOT EXISTS \`$PROJECT_ID.$GOLD_DATASET.operational_mart\` (scenario_id STRING,entity_type STRING,entity_id STRING,sku_id STRING,store_id STRING,warehouse_id STRING,quantity INT64,status STRING,observed_at TIMESTAMP,ingestion_mode STRING)"
Q "DELETE FROM \`$PROJECT_ID.$GOLD_DATASET.operational_mart\` WHERE scenario_id='$BATCH_RUN_ID'; INSERT INTO \`$PROJECT_ID.$GOLD_DATASET.operational_mart\` SELECT '$BATCH_RUN_ID','ORDER',order_id,sku_id,store_id,warehouse_id,quantity,quality_status,occurred_at,'batch' FROM \`$PROJECT_ID.$SILVER_DATASET.pedidos\` WHERE order_id='ORD-$BATCH_RUN_ID' AND quality_status='VALID'; INSERT INTO \`$PROJECT_ID.$GOLD_DATASET.operational_mart\` SELECT '$BATCH_RUN_ID','INVENTORY',snapshot_id,sku_id,store_id,warehouse_id,on_hand_qty-reserved_qty,quality_status,effective_at,'batch' FROM \`$PROJECT_ID.$SILVER_DATASET.inventario\` WHERE snapshot_id LIKE CONCAT('$BATCH_RUN_ID',':%') AND quality_status='VALID'"
printf 'SCRIPT 57: 1 — seis dominios curados; Gold CU01-CU03 y mart materializados\n' > "$ROOT/state/$DEMO_RUN_ID/batch_productivo_gold_ok.txt"
echo 'SCRIPT 57: 1 — Silver, CU01-CU03 y mart materializados'
